package career.assistant.application.audit;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="submission_attempts") public class SubmissionAttempt {
 @Id @GeneratedValue private UUID id; @Column(name="application_id",nullable=false) private UUID applicationId; @Column(name="owner_subject",nullable=false) private String ownerSubject; @Column(name="ats_provider",nullable=false) private String atsProvider; @Column(name="source_fingerprint",nullable=false) private String sourceFingerprint; @Column(name="idempotency_key",nullable=false,unique=true) private String idempotencyKey; @Column(name="request_fingerprint",nullable=false) private String requestFingerprint; @Enumerated(EnumType.STRING) @Column(nullable=false) private SubmissionAttemptState state; @Column(name="confirmation_reference") private String confirmationReference; @Column(name="confirmation_url") private String confirmationUrl; @Column(name="failure_category") private String failureCategory; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @Column(name="started_at") private OffsetDateTime startedAt; @Column(name="completed_at") private OffsetDateTime completedAt;
 @PrePersist void created(){if(createdAt==null)createdAt=OffsetDateTime.now();}
 public UUID getId(){return id;} public UUID getApplicationId(){return applicationId;} public void setApplicationId(UUID v){applicationId=v;} public String getOwnerSubject(){return ownerSubject;} public void setOwnerSubject(String v){ownerSubject=v;} public String getAtsProvider(){return atsProvider;} public void setAtsProvider(String v){atsProvider=v;} public String getSourceFingerprint(){return sourceFingerprint;} public void setSourceFingerprint(String v){sourceFingerprint=v;} public String getIdempotencyKey(){return idempotencyKey;} public void setIdempotencyKey(String v){idempotencyKey=v;} public String getRequestFingerprint(){return requestFingerprint;} public void setRequestFingerprint(String v){requestFingerprint=v;} public SubmissionAttemptState getState(){return state;} public void setState(SubmissionAttemptState v){state=v;} public String getConfirmationReference(){return confirmationReference;} public void setConfirmationReference(String v){confirmationReference=v;} public String getConfirmationUrl(){return confirmationUrl;} public void setConfirmationUrl(String v){confirmationUrl=v;} public String getFailureCategory(){return failureCategory;} public void setFailureCategory(String v){failureCategory=v;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getStartedAt(){return startedAt;} public void setStartedAt(OffsetDateTime v){startedAt=v;} public OffsetDateTime getCompletedAt(){return completedAt;} public void setCompletedAt(OffsetDateTime v){completedAt=v;}
}
